const randomNumber = Math.floor(Math.random() * 100000);

pm.variables.set("name", `Test User ${randomNumber}`);
pm.variables.set("email", `testuser${randomNumber}@example.com`);
pm.variables.set("password", "Test123!!");

const response = pm.response.json();

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response has access_token", function () {
    pm.expect(response).to.have.property("access_token");
    pm.expect(response.access_token).to.be.a("string");
    pm.expect(response.access_token).to.not.be.empty;
});

pm.test("Token type is bearer", function () {
    pm.expect(response.token_type).to.eql("bearer");
});

pm.test("Response has user object", function () {
    pm.expect(response).to.have.property("user");
    pm.expect(response.user).to.be.an("object");
});

pm.test("User fields are correct", function () {
    pm.expect(response.user).to.have.property("id");
    pm.expect(response.user.id).to.be.a("number");

    pm.expect(response.user).to.have.property("name");
    pm.expect(response.user.name).to.be.a("string");

    pm.expect(response.user).to.have.property("email");
    pm.expect(response.user.email).to.be.a("string");

    pm.expect(response.user).to.have.property("role");
    pm.expect(response.user.role).to.be.a("string");

    pm.expect(response.user).to.have.property("subscription_type");
    pm.expect(response.user.subscription_type).to.be.a("string");

    pm.expect(response.user).to.have.property("subscription_expires_at");
    pm.expect(response.user.subscription_expires_at).to.be.a("string");
});
